import{_ as a,o as r,c as t,a5 as i}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"Halides","description":"","frontmatter":{"title":"Halides","mineralGroup":"halides"},"headers":[],"relativePath":"classification/mineral-groups/halides.md","filePath":"classification/mineral-groups/halides.md","lastUpdated":1790876393000}'),l={name:"classification/mineral-groups/halides.md"};function s(o,e,n,c,d,p){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="halides" tabindex="-1">Halides <a class="header-anchor" href="#halides" aria-label="Permalink to &quot;Halides&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Halides are noted in gemology for color-center phenomena:</p><ul><li><strong>Fluorite</strong> (CaF₂): exhibits multiple color-center hues (blue, purple, green) — the classical subject of color-center theory</li><li><strong>Halite</strong> (NaCl): purple variety &quot;purple rock salt&quot; is color- center produced</li><li><strong>Cryolite</strong>: rare fluoride gem</li></ul><h2 id="formula-class" tabindex="-1">Formula Class <a class="header-anchor" href="#formula-class" aria-label="Permalink to &quot;Formula Class&quot;">​</a></h2><p>MX (X = F, Cl, Br, I)</p><h2 id="crystal-structure" tabindex="-1">Crystal Structure <a class="header-anchor" href="#crystal-structure" aria-label="Permalink to &quot;Crystal Structure&quot;">​</a></h2><p>Halide anions (F⁻, Cl⁻) bond with metal cations through ionic interactions. Typical structures: fluorite-type (CaF₂ cubic), halite-type (NaCl cubic). Low hardness and perfect cleavage make halides among the most delicate gem materials.</p><h2 id="representative-gem-species" tabindex="-1">Representative Gem Species <a class="header-anchor" href="#representative-gem-species" aria-label="Permalink to &quot;Representative Gem Species&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Formula</th><th>Subgroup</th></tr></thead><tbody><tr><td>Fluorite / 萤石</td><td>CaF₂</td><td>fluorite</td></tr></tbody></table><p><em>See the <a href="./intro.html">mineral group overview</a>.</em></p><aside class="gem-reference-block" aria-labelledby="gem-reference-title"><p class="gem-reference-block__eyebrow">SOURCE TRACE</p><h2 id="gem-reference-title">References &amp; Evidence Boundary</h2><p class="gem-reference-block__intro">This page supports learning and retrieval; the sources document the knowledge basis and do not make this page sufficient for identifying a specific specimen.</p><ul><li><a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA: Gem Species, Varieties, and Groups</a><span>Relationships among mineral species, gem varieties, and mineral groups</span><small>Open source ↗</small></li><li><a href="https://www.mindat.org/" target="_blank" rel="noreferrer">Mindat mineral database</a><span>Mineral names, chemistry, and classification lookup</span><small>Open source ↗</small></li></ul></aside>',12)])])}const m=a(l,[["render",s]]);export{u as __pageData,m as default};
